-- Cultureland 사용내역 동기화 (2026-04-22)
-- 배경: 협력사(컬쳐랜드) 일대사 데이터상 사용된 PIN 중, 우리 DB에는 EXPIRED로 남아있던 건 USED로 보정
-- 원본: cultureland.md (매칭 2308건 = 온라인 643건 + 오프라인 1665건, 스킵 0건)
-- 매칭: order_delivery.id = 업체승인거래번호 뒷자리 숫자, 안전장치로 bar_code(= cultureland ScratchNo/PIN) 일치 확인
-- 주의: 컬쳐랜드의 "핀번호(16자리)"는 우리 DB의 bar_code. coupon_num 은 CertNo 라서 다름.
-- 오프라인사용(충전날짜 없음)은 trade_at = 발송일자 + 60일 12:00:00 로 설정
-- 실행 방식: START TRANSACTION 상태에서 SELECT 로 결과 확인 후 수동으로 COMMIT / ROLLBACK

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS _cultureland_sync;
CREATE TEMPORARY TABLE _cultureland_sync (
  id BIGINT PRIMARY KEY,
  bar_code VARCHAR(256) NOT NULL,
  trade_at DATETIME NOT NULL
);


-- 1) 업데이트 대상 프리뷰
SELECT COUNT(*) AS will_update
FROM order_delivery od
INNER JOIN _cultureland_sync src
  ON od.id = src.id AND od.bar_code = src.bar_code
WHERE od.coupon_status = 'EXPIRED';

-- 2) 매칭되지만 EXPIRED가 아닌 건 (참고용 - 덮어쓰지 않음)
SELECT od.id, od.bar_code, od.coupon_status, od.trade_at, src.trade_at AS partner_trade_at
FROM order_delivery od
INNER JOIN _cultureland_sync src
  ON od.id = src.id AND od.bar_code = src.bar_code
WHERE od.coupon_status <> 'EXPIRED';

-- 3) bar_code(PIN) 불일치 건 (참고용 - id 는 같은데 PIN 이 다름)
SELECT src.id, src.bar_code AS partner_bar_code, od.bar_code AS our_bar_code, od.coupon_status
FROM _cultureland_sync src
LEFT JOIN order_delivery od ON od.id = src.id
WHERE od.id IS NOT NULL AND od.bar_code <> src.bar_code;

-- 4) 실제 업데이트 (EXPIRED → USED + trade_at 세팅)
UPDATE order_delivery od
INNER JOIN _cultureland_sync src
  ON od.id = src.id AND od.bar_code = src.bar_code
SET
  od.coupon_status = 'USED',
  od.trade_at = src.trade_at
WHERE od.coupon_status = 'EXPIRED';

-- 5) 업데이트 후 확인
SELECT COUNT(*) AS updated_now_used
FROM order_delivery od
INNER JOIN _cultureland_sync src
  ON od.id = src.id AND od.bar_code = src.bar_code
WHERE od.coupon_status = 'USED';

DROP TEMPORARY TABLE IF EXISTS _cultureland_sync;

-- 결과 확인 후 수동 실행:
-- COMMIT;
-- ROLLBACK;
